"""Turn shared/fixtures/money.json into the pgTAP file supabase/tests/money_fixtures.test.sql.

CI regenerates it and fails if the committed file differs.
Run: python3 shared/fixtures/gen_money_sql.py
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
fix = json.loads((ROOT / "shared/fixtures/money.json").read_text())


def lit(v):
    if v is None:
        return "null"
    if isinstance(v, str):
        return "'" + v.replace("'", "''") + "'"
    return str(v)


lines = [
    "-- GENERATED by shared/fixtures/gen_money_sql.py from shared/fixtures/money.json. Do not edit.",
    "begin;",
    "create extension if not exists pgtap with schema extensions;",
    "set search_path = extensions, public;",
    f"select plan({len(fix['cases'])});",
]
for i, c in enumerate(fix["cases"]):
    a, op, e = c["args"], c["op"], c["expect"]
    desc = lit(f"{i} {op} {json.dumps(a, sort_keys=True)}")
    if op == "exponent":
        got, want = f"ref.money_exponent({lit(a['currency'])})", lit(e)
    elif op == "div_round":
        got, want = f"ref.money_div_round({a['n']}::numeric, {a['d']}::numeric)", f"{e}::numeric"
    elif op == "parse":
        got, want = f"ref.money_parse({lit(a['amount'])}, {lit(a['currency'])})", f"{e}::bigint"
    elif op == "format":
        got, want = f"ref.money_format({a['minor']}::bigint, {lit(a['currency'])})", lit(e)
    elif op == "convert":
        usd = "null" if a["usd_per_eur"] is None else f"{a['usd_per_eur']}::numeric"
        got = f"ref.money_convert({a['minor']}::bigint, {lit(a['from'])}, {lit(a['to'])}, {usd})"
        want = f"{e}::bigint"
    elif op == "allocate":
        got = f"ref.money_allocate({a['minor']}::bigint, array{a['weights']}::int[])"
        want = f"array{e}::bigint[]"
    else:
        raise SystemExit(f"unknown op {op}")
    lines.append(f"select is({got}, {want}, {desc});")
lines += ["select * from finish();", "rollback;", ""]
out = ROOT / "supabase/tests/money_fixtures.test.sql"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text("\n".join(lines))
print(f"{len(fix['cases'])} assertions -> {out}")
